fn is_palindrome(s: &Str) -> Bool {
    let chars: Vec<Str> = chars(s).collect();
    let len = len(&chars);
    let mut i = 0;
    let mut j = len - 1;
    while i < j {
        if chars[i] != chars[j] {
            return false;
        }
        i += 1;
        j -= 1;
    }
    true
}

